import java.nio.charset.StandardCharsets;
import java.util.Base64;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.jwt.JwtDecoder;

public final class TokenReader {
    private final JwtDecoder decoder; // configured with trusted key, issuer and validators

    public TokenReader(JwtDecoder decoder) {
        this.decoder = decoder;
    }

    public void explainStructure(String compactJwt) {
        String[] parts = compactJwt.split("\\.");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Not a three-part compact JWS");
        }
        System.out.println(new String(Base64.getUrlDecoder().decode(parts[0]), StandardCharsets.UTF_8));
        System.out.println(new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8));
        // Decoding above is only inspection. It does not authenticate the token.
    }

    public Jwt validate(String compactJwt) {
        return decoder.decode(compactJwt); // trust only the configured decoder's result
    }
}

import io.jsonwebtoken.Jwts;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Date;
import java.util.UUID;
import javax.crypto.SecretKey;

public final class JwtClaimsService {
    private final SecretKey signingKey; // supplied by approved key management
    private final Clock clock;
    private final Duration accessTokenLifetime;

    public JwtClaimsService(SecretKey signingKey, Clock clock, Duration accessTokenLifetime) {
        this.signingKey = signingKey;
        this.clock = clock;
        this.accessTokenLifetime = accessTokenLifetime;
    }

    public String createAccessToken(String userId, String scope) {
        Instant now = clock.instant();
        return Jwts.builder()
            .issuer("https://auth.example")
            .subject(userId)
            .audience().add("orders-api").and()
            .issuedAt(Date.from(now))
            .expiration(Date.from(now.plus(accessTokenLifetime)))
            .id(UUID.randomUUID().toString())
            .claim("scope", scope)
            .signWith(signingKey)
            .compact();
    }
}

