import io.jsonwebtoken.Jwts;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Date;
import javax.crypto.SecretKey;

public final class JwtService {
    private final SecretKey signingKey; // inject from approved key management
    private final Clock clock;
    private final Duration accessTokenLifetime;

    public JwtService(SecretKey signingKey, Clock clock, Duration accessTokenLifetime) {
        this.signingKey = signingKey;
        this.clock = clock;
        this.accessTokenLifetime = accessTokenLifetime;
    }

    public String generateToken(String subject) {
        Instant now = clock.instant();
        return Jwts.builder()
            .issuer("https://auth.example")
            .subject(subject)
            .audience().add("orders-api").and()
            .issuedAt(Date.from(now))
            .expiration(Date.from(now.plus(accessTokenLifetime)))
            .signWith(signingKey)
            .compact();
    }
}

// A receiving Spring API normally configures OAuth 2.0 Resource Server
// with a trusted issuer or key and audience validation instead of hand-parsing.

@Configuration
public class ApiSecurityConfig {

    @Bean
    SecurityFilterChain apiSecurity(HttpSecurity http) throws Exception {
        http
            .securityMatcher("/api/**")
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated())
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .csrf(csrf -> csrf.disable()) // this chain accepts an explicit bearer header
            .oauth2ResourceServer(resourceServer -> resourceServer.jwt(Customizer.withDefaults()));
        return http.build();
    }
}

// application.properties
// spring.security.oauth2.resourceserver.jwt.issuer-uri=https://issuer.example

// Resource Server supplies bearer extraction, decoder validation,
// Authentication creation, SecurityContext handling, and 401 integration.

```java
// A browser client may read the token from JavaScript storage and add it to a header.
// This server returns the raw token in the response body:
@PostMapping("/login")
public Map<String, String> login(@RequestBody LoginRequest req) {
    authenticate(req);
    String jwt = jwtService.generateToken(req.username());
    return Map.of("token", jwt); // storage is a separate client-side decision
}
```
If a browser persists this token in localStorage, injected script in that origin can copy it. Native applications should use platform-protected credential storage instead of browser storage advice.

```java
// Cookie attributes must match the real origin and sign-in flow.
@PostMapping("/login")
public ResponseEntity<Void> login(@RequestBody LoginRequest req) {
    authenticate(req);
    String jwt = jwtService.generateToken(req.username());
    ResponseCookie cookie = ResponseCookie.from("access_token", jwt)
        .httpOnly(true)        // document.cookie cannot read the value
        .secure(true)          // send only over HTTPS
        .sameSite("Lax")     // example policy; choose from the real flow
        .path("/api")        // narrow the scope where practical
        .maxAge(accessTokenLifetime)
        .build();
    return ResponseEntity.noContent()
        .header(HttpHeaders.SET_COOKIE, cookie.toString())
        .build();
}
```
The browser sends a matching cookie automatically, so state-changing requests still need the application's CSRF controls. HttpOnly reduces token theft but does not stop injected script from making requests through the page.

```java
// Stateful: a successful form login can be saved in an HTTP session.
@Bean
SecurityFilterChain chain(HttpSecurity http) throws Exception {
    return http
        .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
        .formLogin(Customizer.withDefaults())
        .sessionManagement(s -> s
            .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED))
        .build();
}
```
Central session invalidation is direct. Multiple instances can use sticky routing or a shared session store; Redis is one possible store, not a requirement.

```java
// Stateless HTTP-session policy; Resource Server validates bearer JWTs.
@Bean
SecurityFilterChain chain(HttpSecurity http) throws Exception {
    return http
        .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
        .sessionManagement(s -> s
            .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .oauth2ResourceServer(oauth -> oauth.jwt(Customizer.withDefaults()))
        .build();
}
```
CSRF configuration still depends on whether a browser sends the credential automatically. Early revocation can be added when the risk requires it, at the cost of extra state or lookups.
